SELECT extensions.is(internal.parse_initial_media_profile(v->>'profile_canonical'),v->'profile','shared closed profile '||i) FROM media_vectors;
SELECT extensions.is(internal.initial_media_contract_digest('profile',v->>'profile_canonical'),v->>'profile_digest','shared profile digest '||i) FROM media_vectors;
SELECT extensions.ok(internal.valid_initial_media_assignment_pair(internal.initial_canonical(v->'candidate'),v->>'assignment_canonical'),'shared candidate/assignment pair '||i) FROM media_vectors;
SELECT extensions.lives_ok(format('SELECT internal.assert_initial_media_profile_matches(%L,%L)',internal.initial_canonical(v->'candidate'),v->>'profile_canonical'),'entire cohort matches '||i) FROM media_vectors;
SELECT extensions.ok(NOT internal.valid_initial_media_assignment_pair(internal.initial_canonical(v->'candidate'),internal.initial_canonical((v->'assignment')-key)),'required assignment field '||key) FROM media_vectors CROSS JOIN LATERAL jsonb_object_keys(v->'assignment') key;
SELECT extensions.ok(NOT internal.valid_initial_media_assignment_pair(internal.initial_canonical(v->'candidate'),internal.initial_canonical(jsonb_set(v->'assignment','{candidate_digest}',to_jsonb(repeat('0',64))))),'reject cross-paired digest '||i) FROM media_vectors;
SELECT extensions.is((SELECT initial_analysis_lifecycle_enabled FROM internal.initial_analysis_rollout),FALSE,'activation remains disabled');
SELECT extensions.is((SELECT count(*) FROM internal.initial_preparation_profiles),0::BIGINT,'no live preparation profiles seeded');
SELECT extensions.is((SELECT count(*) FROM internal.initial_preparation_source_backends),0::BIGINT,'no source backends seeded');
SELECT extensions.ok(NOT has_table_privilege(role_name,'internal.'||table_name,privilege),'private catalog/source privilege '||role_name||'/'||table_name||'/'||privilege)
FROM unnest(ARRAY['anon','authenticated','service_role']) role_name CROSS JOIN unnest(ARRAY['SELECT','INSERT','UPDATE','DELETE','TRUNCATE']) privilege CROSS JOIN unnest(ARRAY['initial_preparation_profiles','initial_preparation_installations','initial_preparation_profile_eligibility','initial_preparation_source_backends','initial_preparation_backend_eligibility','initial_preparation_selections','initial_preparation_current_selection','initial_preparation_source_fences','initial_preparation_source_registry','initial_preparation_source_mapping']) table_name;
SELECT set_config('request.jwt.claim.role','service_role',TRUE);
SELECT pg_temp.admission_owner('00000000-0000-4000-8000-00000000f001');
CREATE FUNCTION pg_temp.media_create(scan UUID, vector BIGINT DEFAULT 3) RETURNS JSONB LANGUAGE SQL AS $$
 SELECT public.create_initial_preparation_intent('00000000-0000-4000-8000-00000000f001',scan,(SELECT internal.initial_canonical(v->'candidate') FROM media_vectors WHERE i=vector));
$$;
SELECT extensions.throws_ok($$SELECT pg_temp.media_create('00000000-0000-4000-8000-00000000f101')$$,'55000','initial_analysis_unavailable','closed gate rejects before allocation');
UPDATE internal.initial_analysis_rollout SET initial_analysis_lifecycle_enabled=TRUE;
SELECT extensions.throws_ok($$SELECT pg_temp.media_create('00000000-0000-4000-8000-00000000f101')$$,'55000','initial_analysis_preparation_unavailable','empty selector rejects before allocation');
SELECT extensions.is((SELECT count(*) FROM internal.initial_analysis_operation_fences WHERE scan_id='00000000-0000-4000-8000-00000000f101'),0::BIGINT,'failed selection leaves no operation claim');
-- Synthetic transaction-local installation is not storage/runtime qualification.
INSERT INTO internal.initial_preparation_profiles SELECT v->>'profile_digest',v->>'profile_canonical' FROM media_vectors;
INSERT INTO internal.initial_preparation_installations(digest,target_kind,target_digest,evidence_digest,reviewed_revision,installer_protocol)
SELECT internal.initial_media_contract_digest('installation',internal.initial_canonical(value)),value->>'target_kind',value->>'target_digest',value->>'evidence_digest',value->>'reviewed_revision',value->>'installer_protocol' FROM (
 SELECT jsonb_build_object('target_kind','profile','target_digest',v->>'profile_digest','evidence_digest',v#>>'{profile,qualification,evidence_digest}','reviewed_revision',v#>>'{profile,qualification,source_revision}','installer_protocol','reviewed_database_owner_install_v1') value FROM media_vectors) x;
INSERT INTO internal.initial_preparation_profile_eligibility(profile_digest,installation_digest,state) SELECT target_digest,digest,'eligible' FROM internal.initial_preparation_installations WHERE target_kind='profile';
CREATE TEMP TABLE backend_fixture AS SELECT jsonb_build_object('generation','00000000-0000-4000-8000-00000000fb01','provider','r2','direct_endpoint','https://'||repeat('0',32)||'.r2.cloudflarestorage.com','private_bucket','synthetic-only','namespace','initial-preparation/v2','credential_profile','synthetic_only','storage_protocol','conditional_create_permanent_same_key_marker_v1') value;
