CREATE FUNCTION pg_temp.funding_tripwire() RETURNS TRIGGER LANGUAGE PLPGSQL AS $$
BEGIN
 IF current_setting('merian.test_funding_tripwire',TRUE)='on' THEN
  IF TG_TABLE_NAME<>'users' THEN RAISE EXCEPTION 'synthetic_funding_mutation' USING ERRCODE='P0001'; END IF;
  IF NEW.complimentary_entitlement_epoch IS DISTINCT FROM OLD.complimentary_entitlement_epoch THEN
   RAISE EXCEPTION 'synthetic_funding_mutation' USING ERRCODE='P0001'; END IF;
 END IF;
 IF TG_OP='DELETE' THEN RETURN OLD; END IF; RETURN NEW;
END;
$$;
CREATE TRIGGER test_funding_tripwire BEFORE INSERT OR UPDATE OR DELETE ON internal.ai_quota_reservations FOR EACH ROW EXECUTE FUNCTION pg_temp.funding_tripwire();
CREATE TRIGGER test_funding_tripwire BEFORE INSERT OR UPDATE OR DELETE ON internal.ai_quota_counters FOR EACH ROW EXECUTE FUNCTION pg_temp.funding_tripwire();
CREATE TRIGGER test_funding_tripwire BEFORE INSERT OR UPDATE OR DELETE ON internal.complimentary_scan_usage FOR EACH ROW EXECUTE FUNCTION pg_temp.funding_tripwire();
CREATE TRIGGER test_funding_tripwire BEFORE INSERT OR UPDATE OR DELETE ON internal.identification_provider_attempts FOR EACH ROW EXECUTE FUNCTION pg_temp.funding_tripwire();
CREATE TRIGGER test_funding_tripwire BEFORE UPDATE ON public.users FOR EACH ROW EXECUTE FUNCTION pg_temp.funding_tripwire();
SELECT set_config('merian.test_funding_tripwire','on',TRUE);

CREATE TEMP TABLE saved_media AS SELECT i,('00000000-0000-4000-8000-'||lpad((65000+i)::TEXT,12,'0'))::UUID scan,pg_temp.media_create(('00000000-0000-4000-8000-'||lpad((65000+i)::TEXT,12,'0'))::UUID,i) value FROM media_vectors;
SET CONSTRAINTS ALL IMMEDIATE;
SET CONSTRAINTS ALL DEFERRED;
SELECT extensions.is(value->>'outcome','allocated','whole cohort allocated '||i) FROM saved_media;
SELECT extensions.is(value->>'authority','none','allocation carries no execution or upload authority '||i) FROM saved_media;
SELECT extensions.is(pg_temp.media_create(scan,i),value,'exact retry returns original response '||i) FROM saved_media;
SELECT extensions.is(public.get_initial_preparation_status('00000000-0000-4000-8000-00000000f001',scan),value,'status returns saved response '||i) FROM saved_media;
SELECT extensions.ok(internal.initial_preparation_sources_complete(scan),'complete durable cohort '||i) FROM saved_media;
SELECT extensions.is((SELECT count(*) FROM internal.ai_quota_reservations WHERE user_id='00000000-0000-4000-8000-00000000f001'),0::BIGINT,'allocation never funds');
SELECT extensions.throws_ok(format('SELECT public.finalize_initial_preparation(%L,%L,%L)','00000000-0000-4000-8000-00000000f001',scan,value->>'assignment_digest'),'55000','initial_analysis_preparation_required','media finalization is closed '||i) FROM saved_media;
-- Strong erasure and expiry exercise the actual preparation owner before enrollment.
SELECT extensions.throws_ok(format('SELECT public.create_initial_preparation_intent(%L,%L,%L)','00000000-0000-4000-8000-00000000f001',scan,(SELECT internal.initial_canonical(jsonb_set(v->'candidate','{source_plan,sources,0,source_sha256}',to_jsonb(repeat('f',64)))) FROM media_vectors WHERE i=saved_media.i)), '22023','initial_analysis_identity_conflict','conflicting exact retry rejects '||i) FROM saved_media;
CREATE TEMP TABLE media_service_request AS SELECT internal.initial_canonical(v->'candidate') candidate FROM media_vectors WHERE i=3;
GRANT SELECT ON media_service_request TO service_role;
SET LOCAL ROLE service_role;
SELECT public.create_initial_preparation_intent('00000000-0000-4000-8000-00000000f001','00000000-0000-4000-8000-00000000f111',(SELECT candidate FROM media_service_request))->>'outcome';
SET CONSTRAINTS ALL IMMEDIATE;
RESET ROLE;
SET CONSTRAINTS ALL DEFERRED;
SELECT extensions.ok(internal.initial_preparation_sources_complete('00000000-0000-4000-8000-00000000f111'),'service-role deferred validation has its narrow definer access');
SELECT public.cancel_initial_analysis('00000000-0000-4000-8000-00000000f001','00000000-0000-4000-8000-00000000f111')->>'dispatch';
SELECT pg_temp.media_create('00000000-0000-4000-8000-00000000f112')->>'outcome';
-- Fixture-only expiry; no production mutation bypass is accepted.
SET CONSTRAINTS ALL IMMEDIATE;
ALTER TABLE internal.initial_analysis_preparation_intents DISABLE TRIGGER guard_initial_preparation_storage;
UPDATE internal.initial_analysis_preparation_intents SET created_at='2000-01-01T00:00:00Z',expires_at='2000-01-01T00:05:00Z' WHERE scan_id='00000000-0000-4000-8000-00000000f112';
ALTER TABLE internal.initial_analysis_preparation_intents ENABLE TRIGGER guard_initial_preparation_storage;
SET CONSTRAINTS ALL DEFERRED;
SELECT extensions.is(public.get_initial_preparation_status('00000000-0000-4000-8000-00000000f001','00000000-0000-4000-8000-00000000f112'),'{"version":2,"variant":"media_sources","outcome":"expired","authority":"none"}'::JSONB,'expiry has closed media response and C1 erasure');
SELECT extensions.throws_ok($$SELECT pg_temp.media_create('00000000-0000-4000-8000-00000000f112')$$,'55000','initial_analysis_cancelled','expired identity cannot allocate again');
SELECT pg_temp.media_create('00000000-0000-4000-8000-00000000f113')->>'outcome';
INSERT INTO internal.scan_deletion_tombstones(scan_id,user_id,completed_at) VALUES('00000000-0000-4000-8000-00000000f113',NULL,clock_timestamp());
SELECT extensions.ok(NOT EXISTS(SELECT 1 FROM internal.initial_preparation_source_registry WHERE scan_id='00000000-0000-4000-8000-00000000f113' AND NOT retired),'pre-row scan deletion retires every source');
SELECT extensions.throws_ok($$SELECT pg_temp.media_create('00000000-0000-4000-8000-00000000f113')$$,'55000','initial_analysis_deleted','late completion/allocation cannot recreate deleted evidence');
SELECT pg_temp.admission_owner('00000000-0000-4000-8000-00000000f002');
SELECT public.create_initial_preparation_intent('00000000-0000-4000-8000-00000000f002','00000000-0000-4000-8000-00000000f114',(SELECT candidate FROM media_service_request))->>'outcome';
DELETE FROM public.users WHERE id='00000000-0000-4000-8000-00000000f002';
SELECT extensions.ok(NOT EXISTS(SELECT 1 FROM internal.initial_preparation_source_registry WHERE scan_id='00000000-0000-4000-8000-00000000f114' AND NOT retired),'raw owner delete retires permanent source destinations');
SELECT extensions.ok(NOT EXISTS(SELECT 1 FROM internal.initial_analysis_preparation_intents WHERE scan_id='00000000-0000-4000-8000-00000000f114'),'raw owner delete erases exact private source evidence');
SELECT pg_temp.admission_owner('00000000-0000-4000-8000-00000000f003');
