SELECT extensions.ok(NOT EXISTS(SELECT 1 FROM internal.initial_preparation_source_registry WHERE scan_id='00000000-0000-4000-8000-00000000f115' AND NOT retired),'supported account detachment retires cohort');
SELECT pg_temp.media_create('00000000-0000-4000-8000-00000000f116')->>'outcome';
-- Conservative safety probe: irreversibly retire one source without claiming
