SELECT extensions.throws_ok($$UPDATE internal.initial_preparation_source_fences SET state='retired' WHERE scan_id='00000000-0000-4000-8000-00000000f116'$$,'22023','initial_analysis_storage_immutable','raw fence retirement requires terminal erasure predicate');
SELECT extensions.throws_ok($$UPDATE internal.initial_preparation_source_registry SET retired=TRUE WHERE scan_id='00000000-0000-4000-8000-00000000f116'$$,'22023','initial_analysis_storage_immutable','raw registry retirement cannot bypass terminal fence');
-- Privileged fault injection to qualify conservative C1, not a permitted writer.
SET CONSTRAINTS ALL IMMEDIATE;
