CREATE FUNCTION pg_temp.partial_retirement() RETURNS TEXT LANGUAGE PLPGSQL AS $$
BEGIN
 PERFORM internal.fence_initial_analysis_erasure('00000000-0000-4000-8000-00000000f118');
 PERFORM internal.retire_initial_preparation_source_objects('00000000-0000-4000-8000-00000000f118');
 SET CONSTRAINTS ALL IMMEDIATE;
 RETURN 'unexpected_success';
EXCEPTION WHEN OTHERS THEN RETURN SQLSTATE||':'||SQLERRM;
END; $$;
SELECT extensions.is(pg_temp.partial_retirement(),'23514:initial_analysis_source_cohort_invalid','partial legal retirement cannot commit while private intent survives');
SELECT public.cancel_initial_analysis('00000000-0000-4000-8000-00000000f001','00000000-0000-4000-8000-00000000f118')->>'dispatch';
