SELECT extensions.lives_ok(format('SELECT public.cancel_initial_analysis(%L,%L)','00000000-0000-4000-8000-00000000f001',scan),'C1 retires even revoked cohort '||i) FROM saved_media;
SET CONSTRAINTS ALL IMMEDIATE;
SELECT extensions.is((SELECT count(*) FROM internal.initial_analysis_preparation_intents WHERE owner_id='00000000-0000-4000-8000-00000000f001'),0::BIGINT,'C1 erases all private candidates and assignments');
