CREATE TEMP TABLE claim AS SELECT public.claim_initial_preparation_source_erasure() value;
SELECT extensions.is(value->>'outcome','claimed','retired source exposes metadata-only cleanup claim') FROM claim;
SELECT extensions.throws_ok(format('UPDATE internal.initial_preparation_source_registry SET claim_token=gen_random_uuid() WHERE object_id=%L',value#>>'{object,object_id}'),'22023','initial_analysis_storage_immutable','raw DML cannot replace live cleanup token') FROM claim;
SELECT extensions.throws_ok(format('UPDATE internal.initial_preparation_source_registry SET claim_expires_at=clock_timestamp()+INTERVAL ''1 hour'' WHERE object_id=%L',value#>>'{object,object_id}'),'22023','initial_analysis_storage_immutable','raw DML cannot extend a live lease') FROM claim;
SELECT extensions.throws_ok($$UPDATE internal.initial_preparation_source_registry SET marker_confirmed=TRUE WHERE retired AND claim_token IS NULL AND NOT marker_confirmed$$,'22023','initial_analysis_storage_immutable','marker acknowledgement requires a live claim');

SELECT extensions.is(public.finish_initial_preparation_source_erasure((value#>>'{object,object_id}')::UUID,gen_random_uuid(),TRUE)->>'outcome','stale','unrelated token cannot acknowledge') FROM claim;
SELECT extensions.is(public.finish_initial_preparation_source_erasure((value#>>'{object,object_id}')::UUID,(value#>>'{object,claim_token}')::UUID,FALSE)->>'outcome','released','failed marker attempt releases without acknowledgement') FROM claim;
SELECT extensions.ok(NOT marker_confirmed AND claim_token IS NULL AND retired,'failed attempt retains permanent retirement without marker proof') FROM internal.initial_preparation_source_registry WHERE object_id=(SELECT (value#>>'{object,object_id}')::UUID FROM claim);
UPDATE claim SET value=public.claim_initial_preparation_source_erasure();
SELECT extensions.is(value->>'outcome','claimed','failed marker attempt can be reclaimed') FROM claim;
CREATE TEMP TABLE expired_claim AS SELECT value FROM claim;
-- Fixture-only clock movement; production guard already rejects lease rewrites.
SET CONSTRAINTS ALL IMMEDIATE;
ALTER TABLE internal.initial_preparation_source_registry DISABLE TRIGGER guard_initial_preparation_source_registry;
UPDATE internal.initial_preparation_source_registry SET claim_expires_at='2000-01-01T00:00:00Z' WHERE object_id=(SELECT (value#>>'{object,object_id}')::UUID FROM claim);
ALTER TABLE internal.initial_preparation_source_registry ENABLE TRIGGER guard_initial_preparation_source_registry;
SET CONSTRAINTS ALL DEFERRED;
SELECT extensions.is(public.finish_initial_preparation_source_erasure((value#>>'{object,object_id}')::UUID,(value#>>'{object,claim_token}')::UUID,TRUE)->>'outcome','stale','expired token cannot acknowledge marker') FROM expired_claim;
UPDATE claim SET value=public.claim_initial_preparation_source_erasure();
SELECT extensions.is(public.finish_initial_preparation_source_erasure((value#>>'{object,object_id}')::UUID,(value#>>'{object,claim_token}')::UUID,TRUE)->>'outcome','stale','old token cannot settle replacement lease') FROM expired_claim;

SELECT extensions.is(public.finish_initial_preparation_source_erasure((value#>>'{object,object_id}')::UUID,(value#>>'{object,claim_token}')::UUID,TRUE)->>'outcome','acknowledged','exact live token acknowledges trusted marker') FROM claim;
SELECT extensions.is(public.finish_initial_preparation_source_erasure((value#>>'{object,object_id}')::UUID,(value#>>'{object,claim_token}')::UUID,TRUE)->>'outcome','stale','consumed token cannot acknowledge twice') FROM claim;
SELECT extensions.throws_ok($$UPDATE internal.initial_preparation_source_registry SET retired=FALSE$$,'22023','initial_analysis_storage_immutable','retirement is irreversible');
SELECT extensions.throws_ok($$DELETE FROM internal.initial_preparation_source_registry$$,'22023','initial_analysis_storage_immutable','permanent registry survives deletion');
SELECT extensions.throws_ok($$UPDATE internal.initial_preparation_source_registry SET marker_confirmed=FALSE WHERE marker_confirmed$$,'22023','initial_analysis_storage_immutable','marker confirmation cannot reopen data');
SELECT * FROM extensions.finish();
ROLLBACK;
